INSERT INTO `lab_migration_experiment` (`id`, `proposal_id`, `number`, `title`, `description`) VALUES
(9,	8,	1,	'Dummy exp',	'echo \"mailhub=10.0.2.2:25\" > /etc/ssmtp/ssmtp.confecho \"mailhub=10.0.2.2:25\" > /etc/ssmtp/ssmtp.conf'),
(10,	9,	1,	'Test Exp',	'This activity aims to migrate labs that use proprietary software (e.g. OrCAD, PSpice) to eSim. eSim is free/libre and open source and offers the same capabilities for circuit design, simulation, analysis, and PCB design as any other proprietary EDA tool. Hence educational institutions can save a huge amount of money that they may spend on procuring licenses.');
